from itertools import permutations

# Generate all permutations of 0..11
perms = list(permutations(range(12)))

# Initialize an empty grid
grid = [[0]*12 for _ in range(12)]

# Try each permutation as the first row
for perm in perms:
    # Fill in the rest of the grid based on the first row
    for i in range(12):
        for j in range(12):
            grid[i][j] = perm[(i+j) % 12]

    # Check if the grid satisfies the constraints
    valid = True
    for i in range(12):
        for j in range(12):
            if grid[i][j] != perm[(i+j) % 12]:
                valid = False
                break
        if not valid:
            break

    # If the grid is valid, print it and stop
    if valid:
        print([num for row in grid for num in row])
        break
